import { relations, sql } from "drizzle-orm";
import { sqliteTable, text, integer } from "drizzle-orm/sqlite-core";
import { user, organization } from "./db.auth-schema";

// Hand-written tables live here. `db.auth-schema.ts` is generated by
// `bun run auth:generate` and is overwritten on every regeneration.

const createdAtMs = () =>
  integer("created_at", { mode: "timestamp_ms" })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .notNull();

export const medias = sqliteTable("medias", {
  id: text("id")
    .$defaultFn(() => crypto.randomUUID())
    .primaryKey(),
  name: text("name").notNull(),
  url: text("url").notNull(),
  key: text("key").notNull(),
  size: integer("size").notNull(),
  mimeType: text("mime_type").notNull(),
  authorId: text("author_id").references(() => user.id),
  organizationId: text("organization_id").references(() => organization.id, {
    onDelete: "cascade",
  }),
  createdAt: createdAtMs(),
});

export const mediasRelations = relations(medias, ({ one }) => ({
  author: one(user, { fields: [medias.authorId], references: [user.id] }),
  organization: one(organization, {
    fields: [medias.organizationId],
    references: [organization.id],
  }),
}));

export const coreSchema = {
  medias,
  mediasRelations,
};
